export const DATA_21: ReadingTest[] = [
  { id: "rd-026", num: 26, title: "Đề 026", timeMin: 60, parts: [
    { title: "The Benefits of Reading for Children", paragraphs: ["Parents and teachers have long believed that reading books regularly helps children grow in ways that other activities simply cannot match. Recent studies from several countries support this belief, showing that children who read for pleasure most days of the week tend to perform better in school subjects beyond just language classes. This connection appears strongest during the early school years, when children's brains are especially receptive to new vocabulary and ways of expressing ideas. Even short daily reading sessions, some researchers argue, can produce noticeable benefits over time.", "One of the clearest benefits involves vocabulary growth, since books often introduce words that rarely appear in everyday conversation at home or at school. A child who regularly reads stories about animals, for example, will naturally encounter and remember words connected to nature and science topics. This steady exposure builds a foundation of language knowledge long before children formally study these subjects in class. Teachers frequently notice that strong readers can express complex ideas more clearly than classmates who read only occasionally.", "Reading also supports the development of imagination and emotional understanding in young children. When children follow a character through a difficult situation in a story, they often begin imagining how that character feels, which helps them think more carefully about other people's emotions in real life. Picture books and simple novels give children a safe way to explore feelings like fear, sadness, or excitement without experiencing the actual events themselves. Some child psychologists believe this kind of imaginative practice makes children more understanding toward classmates and family members.", "Not all reading experiences produce equal benefits, however, and the type of engagement matters as much as the amount of time spent with a book. A child who reads passively, simply moving their eyes across each page without really thinking about the story, gains far less than one who pauses to ask questions or predict what will happen next. Parents who discuss stories with their children after reading, asking what a character might do differently, tend to see stronger comprehension results than parents who leave reading entirely unsupervised. This finding suggests that conversation around books matters just as much as the books themselves.", "Despite these clear benefits, many children today read for pleasure less often than children did a generation ago, largely because phones, tablets, and video games now compete for their free time. Some schools have responded by setting aside dedicated reading periods during the school day, ensuring that every child spends at least some time with a book regardless of habits at home. Whether these school-based programs can fully replace the reading habits many children no longer develop naturally at home remains an open question among educators."], questions: [{ q: "According to the passage, when does reading's connection to school performance appear strongest?", options: ["During the early school years of a child's life.", "Only after children finish all of primary school.", "During the teenage years when reading habits form.", "Only during the summer holidays away from school."], answer: 0 }, { q: "What is the main idea of the passage?", options: ["Reading builds valuable skills, though its benefits depend on engagement.", "Video games have completely replaced reading among children today.", "Only vocabulary improves when children read books regularly.", "Schools should remove all screens to fix children's reading habits."], answer: 0 }, { q: "The word \"receptive\" in paragraph 1 is closest in meaning to _______.", options: ["resistant", "open", "reflective", "repetitive"], answer: 1 }, { q: "According to the passage, how do children typically learn new vocabulary through reading?", options: ["Teachers formally teach these words before children start reading books.", "Books expose children to words rarely used in daily conversation.", "Children mainly learn new words directly from watching videos.", "Vocabulary growth depends entirely on how old the child is."], answer: 1 }, { q: "The word \"suggests\" in paragraph 4 is closest in meaning to _______.", options: ["proves", "indicates", "requests", "ignores"], answer: 1 }, { q: "According to the passage, which of the following is NOT mentioned as a benefit of reading for children?", options: ["Reading can strengthen emotional understanding toward other people.", "Reading can guarantee higher scores on university entrance exams.", "Reading can build vocabulary connected to science and nature.", "Reading can improve how clearly children express complex ideas."], answer: 1 }, { q: "What can be inferred about children who read passively without engaging with the story?", options: ["They gain fewer comprehension benefits than actively engaged readers.", "They read faster than children who ask questions about stories.", "They generally prefer picture books over simple novels.", "Passive reading was more common a generation ago than today."], answer: 0 }, { q: "According to the passage, what have some schools done in response to declining reading habits?", options: ["They banned phones and tablets entirely from school grounds.", "They removed reading periods to focus on other subjects.", "They set aside specific times during the day for reading.", "They asked parents to stop using tablets at home."], answer: 2 }, { q: "What is the author's overall attitude toward reading's role in children's development?", options: ["The author views reading as valuable, though its impact varies.", "The author dismisses most claims about reading's benefits.", "The author argues reading matters only for language classes.", "The author focuses entirely on criticizing modern schools."], answer: 0 }, { q: "According to the passage, what tends to produce stronger comprehension results in children?", options: ["Parents who leave reading time entirely unsupervised at home.", "Children who read many different books without any discussion.", "Parents who discuss stories and ask about characters afterward.", "Children who read only picture books instead of novels."], answer: 2 }] },
    { title: "The Rising Popularity of Live Concerts Among Young People", paragraphs: ["That ticket sales for live concerts have surged among audiences under thirty even as overall music consumption continues shifting toward streaming platforms might initially seem paradoxical, yet industry analysts increasingly regard the two trends as connected rather than contradictory. Streaming, by making recorded music essentially free at the point of use, has arguably left the live concert as one of the few remaining ways for artists to capture significant revenue directly from devoted fans, a shift that has reshaped how both artists and audiences value the concert experience itself.", "Economists studying the entertainment industry point to a broader behavioral pattern sometimes labeled the experience economy, in which younger consumers increasingly prioritize memorable, shareable experiences over the accumulation of physical possessions that previous generations often valued more highly. A concert, unlike a streamed song, cannot be paused, replayed, or owned in any lasting physical sense, which paradoxically appears to be precisely what makes it feel valuable to audiences already saturated with easily accessible, endlessly repeatable digital content.", "Social media platforms have amplified this dynamic considerably, since attending a concert now generates a steady stream of shareable content, videos, photos, and real-time posts, that extends the event's social value well beyond the several hours spent inside the venue itself. Some researchers suggest that the anticipated act of documenting and sharing an experience has itself become part of what audiences are implicitly paying for when they purchase a ticket, blurring the line between attending an event and performing one's attendance for an online audience.", "Rising ticket prices, however, complicate any straightforwardly celebratory account of this trend, since the average cost of concert tickets has increased considerably faster than general inflation over the past decade, driven partly by dynamic pricing algorithms that adjust prices upward in real time as demand for popular shows intensifies. Younger fans, who often report the tightest household budgets among concertgoers, have increasingly turned to secondary resale markets or shared group purchases to manage costs, a workaround that itself has attracted growing regulatory scrutiny in several countries.", "Some music scholars caution against interpreting the concert boom purely through an economic lens, arguing that live performance retains a communal, almost ritualistic quality that recorded music, however emotionally resonant, structurally cannot replicate: shared physical presence, synchronized crowd reactions, and the unrepeatable specificity of a single unrepeated performance. Whether this communal appeal alone would sustain current attendance levels if ticket prices continued rising unchecked, or whether affordability constraints will eventually suppress demand regardless of the experience's perceived value, remains a question the industry has not yet had to confront at full scale.", "Venue capacity constraints add a further complication rarely discussed alongside pricing debates, since many mid-sized cities lack sufficient large venues to meet touring demand, forcing some artists to skip smaller markets entirely in favor of a handful of major metropolitan stops that can guarantee larger, more predictable audiences. This concentration, several touring industry professionals argue, may be quietly reshaping which regions and demographics get meaningful access to the live concert experience at all, independent of any individual fan's willingness or ability to pay.", "Whatever combination of cultural, economic, and logistical factors ultimately proves most decisive, most analysts studying the trend agree that live music's renewed centrality reflects something more durable than a temporary post-pandemic rebound in social activity. Predicting exactly how affordability pressures, venue constraints, and evolving social media habits will interact over the coming decade, however, remains considerably less certain than the current enthusiasm surrounding concert attendance might suggest."], questions: [{ q: "According to the passage, why has streaming made live concerts more financially important for artists?", options: ["Streaming has made recorded music largely free, pushing revenue toward concerts.", "Streaming platforms now pay artists significantly more than concerts do.", "Concert tickets have become cheaper than streaming subscriptions recently.", "Artists earn most streaming revenue directly from concert attendance instead."], answer: 0 }, { q: "The word \"amplified\" in paragraph 3 is closest in meaning to _______.", options: ["intensified", "recorded", "amplified voice", "diminished"], answer: 0 }, { q: "What is the main idea of the passage?", options: ["Streaming services have caused nearly all concert venues to close.", "Young people's concert enthusiasm reflects several interacting, unresolved factors.", "Rising ticket prices have completely eliminated youth concert attendance.", "Social media alone explains why concerts have grown popular again."], answer: 1 }, { q: "According to the passage, what has driven concert ticket prices to rise faster than general inflation?", options: ["Secondary resale markets have lowered prices for most popular shows.", "Dynamic pricing algorithms raise prices as demand for shows increases.", "Regulatory scrutiny has pushed venues to raise prices deliberately.", "Younger fans have specifically requested higher prices for better seats."], answer: 1 }, { q: "According to the passage, which of the following is NOT mentioned as a factor shaping the current concert boom?", options: ["Younger consumers increasingly value memorable experiences over possessions.", "Concerts generate shareable content that extends their social value.", "Government subsidies for touring artists have expanded substantially worldwide.", "Limited venue capacity in some cities restricts touring options."], answer: 2 }, { q: "What can be inferred about the sustainability of current concert attendance levels?", options: ["Attendance will certainly collapse the moment prices rise any further.", "Whether rising prices might eventually suppress demand remains untested.", "Communal appeal alone has already been proven insufficient on its own.", "Streaming platforms will soon replace live concerts entirely for young fans."], answer: 1 }, { q: "According to the passage, how does venue capacity affect which fans can attend concerts?", options: ["Every mid-sized city now has ample large venues for touring artists.", "Venue shortages may unevenly limit which regions gain concert access.", "Artists prefer smaller markets specifically because of lower costs there.", "Predictable audiences form only in cities with no venue constraints."], answer: 1 }, { q: "The word \"predictable\" in paragraph 6 is closest in meaning to _______.", options: ["reliable", "profitable", "predicted", "unstable"], answer: 0 }, { q: "According to the passage, what have younger fans increasingly done to manage rising ticket costs?", options: ["They have mostly stopped attending live concerts altogether.", "They have turned to resale markets or shared group purchases.", "They have lobbied governments to cap all ticket prices nationally.", "They have shifted entirely back toward streaming instead of concerts."], answer: 1 }, { q: "What is the author's overall stance on explaining the concert attendance boom?", options: ["The author treats the trend as shaped by multiple, unresolved factors.", "The author argues the boom is purely a temporary pandemic rebound.", "The author insists social media is the boom's only real cause.", "The author confidently predicts ticket prices will soon fall sharply."], answer: 0 }] },
    { title: "Artificial Intelligence and the Future of the Workforce", paragraphs: ["That artificial intelligence might eventually perform tasks currently requiring years of specialized human training no longer strikes most economists as far-fetched speculation, yet considerable disagreement persists over whether this shift will primarily displace workers or instead augment their existing capabilities. Surveys of business leaders conducted in recent years reveal enthusiasm about productivity gains alongside genuine uncertainty about how quickly these changes might unfold across different industries and occupational categories.", "Concerns about machines displacing human labor are hardly new, having accompanied major technological shifts stretching back through the mechanization of agriculture and the introduction of industrial assembly lines. Previous waves of automation, economists note, ultimately created more jobs than they eliminated, though the transition periods often proved painful for workers whose specific skills became suddenly obsolete . Whether artificial intelligence will follow this same historical pattern or instead represents a genuinely different kind of disruption remains actively debated among labor economists.", "Unlike earlier automation, which primarily replaced repetitive physical labor on factory floors, current AI systems increasingly perform cognitive tasks once assumed to require distinctly human judgment, drafting legal documents, summarizing lengthy reports, and even generating preliminary medical diagnoses for physician review. This expansion into white-collar territory has unsettled professions that had long considered themselves relatively insulated from automation's reach. Radiologists, paralegals, and financial analysts now find themselves confronting questions about job security that factory workers faced decades earlier.", "Some labor economists argue that AI tools function primarily as augmentation rather than outright replacement, allowing individual workers to handle a greater volume of tasks rather than eliminating entire job categories outright. This view suggests that productivity gains may translate into higher wages for workers who successfully adapt their skills to work alongside these tools. Skeptics counter that this optimistic framing may understate how quickly certain roles, particularly those involving routine analysis or document review, could shrink dramatically even if they never disappear completely.", "Retraining programs designed to help displaced workers transition into new roles face persistent structural challenges, since many such programs assume workers can access reliable internet connections, flexible schedules, and sufficient financial cushioning to survive an extended period without steady income. Workers in mid-career, having invested years developing expertise in a single occupation, often find retraining considerably more difficult than younger workers just entering the labor market. Government-funded programs have shown mixed results, succeeding in some regions while failing to meaningfully reduce unemployment in others facing similar disruption.", "Several economists worry that the benefits of AI-driven productivity gains will flow disproportionately toward highly educated workers and capital owners, while workers in more routine occupations bear the brunt of displacement without capturing a comparable share of the resulting economic gains. This dynamic , if left unaddressed by policy, could widen income inequality considerably beyond levels already documented following previous waves of technological change. Some policymakers have proposed taxing automation directly to fund retraining, though implementation details remain contested.", "Predicting precisely how these competing dynamics, augmentation, displacement, retraining, and inequality, will ultimately interact over the coming decade remains beyond what any single economic model can confidently forecast. What seems reasonably clear is that the workforce transformation already underway will likely prove considerably more uneven across industries, regions, and skill levels than either the most optimistic or the most alarmist predictions currently circulating tend to suggest."], questions: [{ q: "According to the passage, what was the outcome of previous waves of automation?", options: ["Transition periods often proved painful for affected workers.", "They ultimately destroyed more jobs than they created.", "They created jobs only in the technology sector.", "They ultimately produced more new jobs than losses."], answer: 3 }, { q: "The word \"obsolete\" in paragraph 2 is closest in meaning to _______.", options: ["extinct", "outdated", "unpopular", "absolute"], answer: 1 }, { q: "What is the main idea of the passage?", options: ["AI performs cognitive tasks like drafting legal documents.", "Most economists now agree AI mainly creates entirely new jobs.", "AI's workforce effects are debated and likely uneven.", "AI will inevitably eliminate all routine white-collar jobs soon."], answer: 2 }, { q: "The phrase \"This dynamic\" in paragraph 6 refers to _______.", options: ["capital owners", "unequal AI benefit flow", "highly educated workers", "policy proposals"], answer: 1 }, { q: "According to the passage, what do some labor economists argue about AI tools?", options: ["Economists have proven AI never replaces any human worker.", "Most economists agree AI mainly replaces workers outright.", "Skeptics counter that certain roles could shrink dramatically.", "AI mainly assists workers rather than replacing them entirely."], answer: 3 }, { q: "According to the passage, which of the following is NOT mentioned as a challenge related to retraining displaced workers?", options: ["All workers easily access flexible schedules for retraining.", "Government-funded programs have shown mixed results across regions.", "Employers directly cover all retraining costs for their workers.", "Mid-career workers often find retraining considerably more difficult."], answer: 2 }, { q: "What can be inferred about the risk of rising income inequality from AI adoption?", options: ["Income inequality will certainly triple within just one decade.", "Falling inequality is what drives greater AI adoption today.", "Some policymakers have proposed taxing automation directly.", "Income inequality could worsen without deliberate policy intervention."], answer: 3 }, { q: "The word \"insulated\" in paragraph 3 is closest in meaning to _______.", options: ["protected", "immune", "isolated", "insured"], answer: 0 }, { q: "According to the passage, what kinds of tasks does current AI increasingly perform?", options: ["Radiologists and paralegals face new job security questions.", "AI fully replaces physicians in making final diagnoses.", "AI only assists with basic factory floor assembly tasks.", "AI now drafts documents and suggests early medical diagnoses."], answer: 3 }, { q: "What is the author's overall stance on AI's impact on the workforce?", options: ["The author presents the topic as complex and unresolved.", "The author mainly warns that radiologists will lose jobs.", "The author remains fully confident predictions will prove accurate.", "The author strongly advocates taxing automation immediately."], answer: 0 }] },
    { title: "The Genesis of Earth: A 4.6 Billion-Year Journey", paragraphs: ["Not only did the solar system's formation begin with the gravitational collapse of a diffuse molecular cloud roughly 4.6 billion years ago, but the resulting protoplanetary disk of gas and dust also provided, within a comparatively narrow window of several million years, the raw material from which Earth and its planetary neighbors would eventually accrete. Dust grains colliding at low velocities gradually built into pebble-sized aggregates, then kilometer-scale planetesimals, and finally into planetary embryos whose escalating gravitational pull accelerated further accretion, a runaway process that astrophysicists describe as having consumed a geologically brief interval relative to the planet's subsequent history. [1]", "That Earth's early surface endured a molten, largely inhospitable state for tens of millions of years following its initial accretion is a conclusion drawn largely from meteorite composition and computer modeling rather than any surviving direct terrestrial evidence, since rock records from this earliest interval have been almost entirely erased by subsequent geological activity. Differentiation into a dense metallic core, a silicate mantle, and a thin crust proceeded as heavier elements sank under gravity while lighter material rose toward the surface, a process that released substantial gravitational energy as heat and further prolonged the planet's molten condition. A collision with a Mars-sized body, widely hypothesized to have produced the Moon from ejected debris, likely occurred somewhere within this same violent early interval , though the precise timing remains debated among specialists.", "Whether a discrete surge of asteroid and comet impacts, commonly termed the Late Heavy Bombardment, struck the inner solar system roughly 4.1 to 3.8 billion years ago, or whether the cratering record instead reflects a more gradual decline from an already elevated impact rate, remains genuinely contested among planetary scientists. Lunar samples returned by crewed missions initially seemed to support a discrete spike, yet subsequent reanalysis, complicated by dating uncertainties inherent to shock-heated rock, has left open the possibility that no sharply defined bombardment episode occurred at all, only a smoother tapering of an already violent early solar system.", "Not until the planet's surface had cooled sufficiently for water to condense and pool did the earliest oceans begin forming, their origin traceable, according to competing hypotheses, either to volcanic outgassing of water already incorporated into Earth's interior during accretion or to subsequent delivery by water-rich asteroids and comets bombarding the young planet. Isotopic signatures preserved in ancient zircon crystals, some dated to within a few hundred million years of Earth's formation, suggest liquid water may have existed far earlier than once assumed, complicating simple narratives in which a uniformly molten early Earth gradually cooled into a stable, ocean-bearing world only much later. [2]", "Evidence for the earliest life remains stubbornly ambiguous , with claimed microfossils and chemical biosignatures in rocks older than 3.5 billion years routinely subject to renewed scrutiny and, in several prominent cases, outright reinterpretation as non-biological in origin. That life may have originated considerably earlier than any confidently confirmed fossil evidence currently demonstrates is a position several astrobiologists find plausible, given how rapidly conditions suitable for chemistry approximating life's basic requirements appear to have emerged following the planet's earliest bombardment period, yet plausibility alone cannot substitute for evidence that has not yet been definitively recovered.", "Precisely when plate tectonics, the continuous cycle of crustal formation and subduction that shapes Earth's surface today, began operating in something resembling its modern form remains one of the more persistently unsettled questions in Earth science. [3] Some geochemical signatures suggest tectonic-like processes operating as early as 4 billion years ago, while other researchers argue that a single, globally rigid plate persisted until well after 3 billion years ago, with modern-style plate tectonics emerging only gradually thereafter as the planet's interior cooled enough to permit the necessary crustal weakening.", "The Great Oxidation Event, during which atmospheric oxygen rose from negligible trace levels to geologically significant concentrations roughly 2.4 billion years ago, transformed Earth's chemistry so thoroughly that most previously dominant anaerobic organisms were forced into marginal or extinct status within a relatively narrow geological interval. Photosynthesizing cyanobacteria are widely credited with producing this oxygen, though why the atmospheric rise occurred when it did, rather than considerably earlier, given evidence that cyanobacteria may have existed for hundreds of millions of years beforehand, remains a hedged and actively researched question rather than a settled matter. [4]", "Reconstructing this 4.6-billion-year sequence inevitably involves piecing together fragmentary, often contradictory evidence from disciplines as varied as geochemistry, astrophysics, and paleobiology, each contributing constraints that narrow but rarely eliminate genuine uncertainty. Whatever revisions future evidence eventually forces upon this narrative, the broad outline, accretion, differentiation, bombardment, and the gradual emergence of a habitable, oxygenated world, appears unlikely to be overturned wholesale."], questions: [{ q: "According to the passage, what is proposed regarding the Moon's formation?", options: ["A Mars-sized impactor is confirmed to have formed the Moon.", "A Mars-sized impactor definitely never influenced the Moon's formation.", "Several small impactors gradually combined to form the Moon slowly.", "A Mars-sized impactor is hypothesized to have formed the Moon."], answer: 3 }, { q: "The word \"runaway\" in paragraph 1 is closest in meaning to _______.", options: ["explosive", "self-accelerating", "gravitational", "runoff"], answer: 1 }, { q: "What is the main idea of the passage?", options: ["The Moon formed from a single giant impact.", "All planets form through identical, fully understood processes.", "Earth's early history involved violent, still-debated formative stages.", "Scientists have now fully resolved Earth's early history."], answer: 2 }, { q: "The phrase \"this same violent early interval\" in paragraph 2 refers to _______.", options: ["the Moon's formation", "Earth's early molten period", "the precise timing", "a Mars-sized body"], answer: 1 }, { q: "According to the passage, what do zircon isotopic signatures suggest about early liquid water?", options: ["Zircon evidence proves liquid water definitely predates all assumptions.", "Zircon evidence suggests liquid water never existed this early.", "Zircon evidence slightly hints water existed after prior assumptions.", "Zircon evidence suggests liquid water may predate prior assumptions."], answer: 3 }, { q: "According to the passage, which of the following is NOT presented as a genuinely unresolved question in Earth's early history?", options: ["Whether Earth's overall mass has changed since formation is disputed.", "Whether a discrete bombardment spike occurred remains contested.", "When plate tectonics began operating in modern form is unsettled.", "Why oxygen rose when it did rather than earlier is unresolved."], answer: 0 }, { q: "What can be inferred about the reliability of reconstructing Earth's earliest history?", options: ["Every stage of Earth's early history is now fully certain.", "Lunar samples initially seemed to support a discrete spike.", "Better dating methods caused early Earth events to occur later.", "Confidence in this reconstruction varies by evidence type and era."], answer: 3 }, { q: "The word \"ambiguous\" in paragraph 5 is closest in meaning to _______.", options: ["false", "unclear", "biological", "ambitious"], answer: 1 }, { q: "According to the passage, what remains uncertain about the Great Oxidation Event?", options: ["Scientists have definitively explained exactly why oxygen rose then.", "Anaerobic organisms were forced into marginal or extinct status.", "Volcanic outgassing is widely credited with producing this oxygen.", "Cyanobacteria are widely credited, though the timing stays unexplained."], answer: 3 }, { q: "Which of the following square brackets [1] , [2] , [3] , or [4] best indicates where the following sentence could be added? 'This runaway growth phase, however, left no rock record of its own, since nothing durable had yet solidified for it to be preserved within.'", options: ["[1]", "[2]", "[3]", "[4]"], answer: 0 }] },
  ] },
  { id: "rd-029", num: 29, title: "Đề 029", timeMin: 60, parts: [
    { title: "Living Near Volcanoes", paragraphs: ["Millions of people around the world choose to live within sight of an active volcano, even though everyone in the area knows the mountain could erupt again someday. For many families, the decision has less to do with courage than with practical reasons that outsiders sometimes overlook. Some have farmed the same slopes for generations and see no obvious reason to leave land their grandparents once worked. Others are drawn by the volcano itself, since visitors traveling to see its crater or hike its trails bring income that the surrounding town depends on.", "One major reason people settle near volcanoes is the soil itself. Ash and lava, once they break down over time, leave behind minerals that plants absorb easily, which is why crops such as coffee, rice, and vegetables often grow unusually well on volcanic slopes. Farmers in these regions frequently report harvests noticeably larger than those from ordinary farmland nearby. This advantage is not permanent, however, since a fresh eruption can bury the same fields under ash within hours, forcing families to wait months or even years before the soil recovers enough to plant again.", "To reduce the danger, scientists closely monitor active volcanoes using instruments that detect small changes most people would never notice. Seismographs record tiny earthquakes deep underground, while other sensors measure gases escaping through cracks in the rock, since both can rise sharply in the weeks before an eruption. When these signals appear together, officials sometimes have enough warning to evacuate nearby towns before the volcano actually erupts. This early warning can save many lives. It does not, however, always arrive in time to protect everyone nearby, since a small number of eruptions still occur with almost no warning at all.", "The dangers of living near a volcano extend well beyond the lava itself, which usually moves slowly enough for people to walk away from it. Falling ash can collapse roofs, damage crops, and make breathing difficult for anyone without proper protection. Far more dangerous is a pyroclastic flow, a fast-moving cloud of hot gas and rock that can travel down a mountainside within minutes, destroying almost everything in its path. Because such flows move so quickly, distance from the volcano itself often matters more than any amount of preparation.", "Local governments in volcanic regions typically prepare evacuation plans and hold regular drills so that residents know exactly where to go if an alarm sounds. Schools near active volcanoes often teach children what warning signs to watch for and how to reach a safe zone quickly. Even so, some families choose to stay as long as possible during a slow-building crisis, unwilling to abandon a home, a farm, or a family business without being absolutely certain the danger is real."], questions: [{ q: "According to the passage, what advantage does volcanic soil give farmers?", options: ["Ash and lava break down over time and release minerals.", "Volcanic soil often produces larger crop harvests than typical farmland.", "Farmers everywhere report smaller harvests on volcanic slopes.", "Volcanic soil advantage lasts permanently even after a new eruption."], answer: 1 }, { q: "Which of the following best expresses the main idea of the passage?", options: ["People choose to live near volcanoes despite serious ongoing dangers.", "Volcanic soil helps farmers grow unusually large harvests nearby.", "Most people near volcanoes ignore all danger completely.", "Every volcano on Earth provides equal warning before it erupts."], answer: 0 }, { q: "The word \"absorb\" in paragraph 2 is closest in meaning to _______.", options: ["soak up", "erupt", "take in", "absolve"], answer: 2 }, { q: "According to the passage, what is true about volcanic eruption warnings?", options: ["Some eruptions occur with almost no advance warning at all.", "Seismographs continuously record very tiny earthquakes occurring deep underground.", "Every volcano gives officials enough time to evacuate safely.", "Only seismographs, not gas sensors, are used to monitor volcanoes."], answer: 0 }, { q: "According to the passage, which of the following is NOT mentioned as a danger of living near a volcano?", options: ["Falling ash that can collapse roofs and damage crops.", "Poisonous drinking water caused directly by nearby volcanic activity.", "A pyroclastic flow that moves quickly down a mountainside.", "Fields buried under ash after a fresh new eruption."], answer: 1 }, { q: "The word \"It\" in paragraph 3 refers to _______.", options: ["nearby towns affected", "the volcano itself", "the early warning", "officials who evacuate"], answer: 2 }, { q: "According to the passage, why is a pyroclastic flow considered especially dangerous?", options: ["A pyroclastic flow can move down a mountain within minutes.", "Lava usually moves slowly enough for people to walk away.", "A pyroclastic flow typically takes several days to travel downhill.", "Falling ash moves faster than any pyroclastic flow does."], answer: 0 }, { q: "The word \"collapse\" in paragraph 4 is closest in meaning to _______.", options: ["crack", "erupt", "collide", "cave in"], answer: 3 }, { q: "What can be inferred from the passage about families who live near volcanoes?", options: ["Every family near a volcano will eventually be forced to move.", "Better evacuation drills will convince farmers to abandon fertile land.", "Families near volcanoes weigh real danger against real, practical benefits.", "Officials evacuate nearby towns before some volcanoes actually erupt."], answer: 2 }, { q: "What is the author's overall attitude toward people who choose to live near volcanoes?", options: ["Informative and balanced, respecting both the risks and the reasons people stay.", "Strongly alarmed that anyone living near a volcano faces certain death.", "Fully reassured that evacuation plans make volcanic areas completely safe.", "Mildly critical of families who choose not to relocate immediately."], answer: 0 }] },
    { title: "Passport Rules for Children Under Sixteen: What Parents Need to Know", paragraphs: ["Obtaining a passport for a child under sixteen involves a set of requirements that most adults applying for their own documents never encounter, and the reasoning behind these additional steps has less to do with bureaucratic caution than with a specific, well-documented concern: preventing a child from being taken across a border without the knowledge or consent of everyone legally responsible for that child. What looks, on the surface, like extra paperwork is in most cases a direct response to real cases of parental abduction and trafficking that shaped passport policy over recent decades.", "Central to nearly every children's passport application is the requirement that both parents, or both legal guardians, provide consent, typically by signing the application in person or submitting notarized authorization if one parent cannot attend. This requirement holds even when the parents are amicably separated and share custody without dispute, since the rule is designed around the child's legal status rather than the parents' relationship to each other. Exceptions do exist - a sole surviving parent, someone granted full legal custody by a court, or a guardian appointed after both parents are deceased may typically apply alone - but these exceptions generally require documentary proof, not simply a verbal explanation.", "It is this need for reliable identity verification, more than any single administrative rule, that explains why most countries require a child to appear in person when applying for a passport, regardless of age. Even an infant only weeks old typically must be physically present at the application appointment, since photographs and physical descriptions recorded at this stage become part of a document that officials at another border may later need to match against the child actually standing in front of them. Remote or mail-in applications, common for certain adult renewals, are rarely permitted for a first children's passport.", "Once issued, a child's passport tends to remain valid for a considerably shorter period than an adult's, often five years rather than ten, a difference that reflects how quickly a young child's appearance can change. A photograph taken at age three may bear little resemblance to the same child at age eight, undermining the very identity-matching purpose the document exists to serve. Parents are therefore advised to check the expiration date well before a planned trip, since a passport that was valid at booking may quietly expire before departure.", "Cross-border travel involving only one parent introduces further complications that many families do not anticipate until they are already at an airport. Some countries request, though do not universally require, a notarized letter from the non-traveling parent explicitly authorizing the trip, particularly when the child's surname differs from that of the accompanying adult. This requirement is sometimes mistaken for an absolute, universal law rather than the discretionary , border-by-border practice it more often actually is; a document accepted without question at one crossing may be requested in additional, more specific form at another, leaving families to prepare for the stricter possibility rather than assume the more relaxed one will apply.", "Renewing a child's passport is rarely as simple as renewing an adult's, since many governments do not permit the streamlined online or mail-in renewal processes increasingly available to adult applicants. A parent renewing a child's passport typically must repeat much of the original in-person process, including fresh consent from both parents where applicable, precisely because a child's changed appearance and ongoing legal circumstances cannot be reliably confirmed through a form alone.", "Because specific requirements vary considerably from one country to another, and occasionally change with little public notice, parents are generally advised to consult official government sources directly before assuming that a previous application, or another family's experience, accurately predicts their own. What remains consistent across nearly every jurisdiction is the underlying principle: a child's passport belongs to a minor who cannot yet fully consent on their own behalf, and the process is built around that single fact."], questions: [{ q: "According to the passage, why do children's passport applications involve extra requirements?", options: ["Most adults applying for their own documents never encounter these steps.", "They exist mainly to reduce paperwork for government passport offices.", "They mainly exist to help prevent child abduction and trafficking across borders.", "They were created primarily to speed up airport security screening."], answer: 2 }, { q: "The word \"amicably\" in paragraph 2 is closest in meaning to _______.", options: ["in a friendly way", "in a formal way", "in a legal way", "in an audible way"], answer: 0 }, { q: "Which of the following best expresses the main idea of the passage?", options: ["Children's passports are valid for a shorter period than adults' passports.", "Children's passport rules add extra safeguards mainly to protect against abduction.", "Passport rules for children are now simpler than rules for adults.", "Every country enforces identical passport requirements for all children worldwide."], answer: 1 }, { q: "According to the passage, which of the following is NOT mentioned as a requirement or feature of children's passport applications?", options: ["A blood relative must always accompany the child through security.", "Both parents or legal guardians must typically provide their consent.", "The child must usually appear in person at the application.", "The passport is generally valid for a shorter period."], answer: 0 }, { q: "According to the passage, why must a child typically appear in person for a passport application?", options: ["Remote or mail-in applications are common for certain adult renewals.", "In-person appearance is required only for children older than five.", "Photographs are optional for children applying for their first passport.", "Officials need to match the child's actual appearance to the document later."], answer: 3 }, { q: "The phrase \"This requirement\" in paragraph 5 refers to _______.", options: ["border security itself", "the differing surname", "the notarized-letter request", "the accompanying adult"], answer: 2 }, { q: "The word \"discretionary\" in paragraph 5 is closest in meaning to _______.", options: ["judgment-based", "mandatory", "documented", "discreet"], answer: 0 }, { q: "According to the passage, how does renewing a child's passport typically differ from renewing an adult's?", options: ["Adult applicants increasingly have access to streamlined renewal processes.", "Many governments do not allow simplified online renewal for children's passports.", "Children's passports can always be renewed entirely online without an appointment.", "Renewing a child's passport never requires any parental consent again."], answer: 1 }, { q: "What can be inferred from the passage about how parents should approach children's passport rules?", options: ["All countries will eventually adopt identical passport rules for children.", "Simpler adult renewal processes will soon force children's rules to relax too.", "A child's passport photo can look outdated within a few years.", "Parents should verify each country's specific requirements rather than assume they're uniform."], answer: 3 }, { q: "What is the author's overall purpose in writing this passage?", options: ["Practically informative, urging parents toward careful, country-specific preparation.", "Alarmed that most airports will reject single-parent travelers outright.", "Fully reassured that renewal procedures are now identical to adults'.", "Mildly critical of governments for making passport rules unnecessarily strict."], answer: 0 }] },
    { title: "The Global Popularity of Football: More Than Just a Game", paragraphs: ["No other sport commands anything resembling football's global reach, a dominance that becomes stranger the more closely one examines it, since the game itself requires almost no specialized equipment and can be adapted, however roughly, to almost any open space. That very simplicity, some historians argue, is precisely what allowed the sport to spread so effectively during the colonial and industrial upheavals of the nineteenth century, when British sailors, merchants, and administrators carried the game to ports and cities that had little else in common with one another.", "Beneath the spectacle of a single World Cup final lies an economic apparatus considerably larger than most casual viewers appreciate, encompassing broadcasting rights, sponsorship deals, and a transfer market in which a single player's valuation can exceed the annual budget of a mid-sized municipality - and it is this financial scale, rather than the sport's tactical complexity, that increasingly shapes which clubs can compete meaningfully at the highest level. Wealthy ownership groups, many originating from outside the countries whose leagues they now control, have transformed a handful of clubs into entities whose commercial reach rivals that of multinational corporations.", "Sociologists studying fan culture note that football's appeal may rest less on the sport itself than on the sense of belonging it reliably supplies to communities that modern life has otherwise fragmented. A local club, however modest its recent results, tends to offer a form of continuity - the same stadium, the same rivalries, occasionally the same seat - that few other institutions in a rapidly changing city can still provide. This function , some researchers suggest, helps explain why attachment to a struggling club rarely weakens in proportion to its performance on the field.", "Yet the sport's growth has not been free of friction . Persistent allegations of financial irregularity within governing bodies, disputes over which nations should host major tournaments, and recurring accusations that certain competitions serve primarily to launder the reputations of wealthy sponsors have all complicated football's image as a purely unifying force. Defenders of the sport's institutions tend to argue that such controversies, while real, are not fundamentally different from governance failures found in any sufficiently large global industry.", "Less publicly discussed, though increasingly documented, is the working life of professional players themselves, whose careers are typically compressed into a narrow physical window and whose bodies absorb cumulative strain that can produce long-term health consequences extending well past retirement. Studies tracking former professionals report elevated rates of joint deterioration and, among some populations, certain neurological conditions linked to repeated heading of the ball, though researchers caution that establishing a precise causal mechanism, as opposed to a correlational pattern, remains an active and unresolved area of inquiry.", "Technological interventions, most visibly video-assisted refereeing, were introduced with the explicit promise of eliminating clearly incorrect decisions, and in a narrow statistical sense they appear to have reduced certain categories of error. Whether this technical accuracy has actually increased fans' trust in officiating, however, remains far less certain, since surveys conducted after the technology's introduction suggest that perceived fairness depends as much on which outcome a fan's own team receives as on the objective correctness of any single decision.", "Taken together, football's global position appears secure less because the sport has resolved these tensions than because its capacity to generate meaning - economic, communal, and increasingly technological - has so far outpaced whatever controversies periodically threaten to diminish it. Whether that capacity can be sustained indefinitely, or whether accumulating governance and welfare concerns will eventually erode the loyalty the sport has long taken for granted, remains a question current evidence does not allow anyone to answer with real confidence."], questions: [{ q: "According to the passage, what does the passage suggest allowed football to spread so effectively in the nineteenth century?", options: ["British colonial administrators personally organized formal leagues in many port cities.", "The game's basic simplicity greatly aided its rapid worldwide spread.", "Football required extensive costly equipment only wealthy colonizers could afford.", "Industrial upheavals directly forced most governments to adopt football."], answer: 1 }, { q: "The word \"friction\" in paragraph 4 is closest in meaning to _______.", options: ["rubbing", "sponsorship", "tension", "fiction"], answer: 2 }, { q: "Which of the following best expresses the main idea of the passage?", options: ["Football's global dominance combines economic power, communal meaning, and unresolved tensions.", "Video-assisted refereeing has now eliminated all refereeing controversy completely.", "Football's economic scale has now become its only real source of appeal.", "Every sport in the world now generates comparable global economic power."], answer: 0 }, { q: "According to the passage, which of the following is NOT mentioned as a concern surrounding modern football?", options: ["Allegations of financial irregularity within governing bodies.", "Disputes over which nations should host major tournaments.", "Long-term joint deterioration reported among some former professional players.", "A steady decline in football's global broadcast audience."], answer: 3 }, { q: "According to the passage, what do researchers caution about the link between heading the ball and neurological conditions?", options: ["Former players show elevated rates of joint deterioration overall.", "Establishing a precise causal mechanism, not mere correlation, remains genuinely unresolved.", "Player careers are typically compressed into a narrow physical window.", "No researcher has ever studied this specific health question before."], answer: 1 }, { q: "The phrase \"This function\" in paragraph 3 refers to _______.", options: ["the same stadium seat", "modern city life itself", "the sense of continuity", "recent match results"], answer: 2 }, { q: "The word \"compressed\" in paragraph 5 is closest in meaning to _______.", options: ["condensed", "eliminated", "sponsored", "compromised"], answer: 0 }, { q: "According to the passage, what does the passage say about video-assisted refereeing's effect on fan trust?", options: ["The technology has completely eliminated every controversial refereeing decision made.", "Perceived fairness depends on which outcome a fan's team receives.", "No surveys were ever conducted after the technology's introduction.", "Whether it has actually increased fans' trust remains far less certain."], answer: 3 }, { q: "What can be inferred about football's long-term global position, based on the passage?", options: ["Football's popularity will definitely collapse once scandals are exposed.", "Its long-term dominance may not be fully guaranteed.", "Increased fan trust will directly cause bigger transfer valuations.", "Former players report elevated rates of joint deterioration overall."], answer: 1 }, { q: "What is the author's overall attitude toward football's global position, as conveyed in the passage?", options: ["Uncritically celebratory, ignoring all of football's real controversies entirely.", "Deeply cynical, viewing football's popularity as built purely on manipulation.", "A balanced view, respecting football's appeal while noting real problems.", "Mostly indifferent to whether football maintains its global cultural position."], answer: 2 }] },
    { title: "Malaysia: A Nation of Cultural Diversity and Economic Growth", paragraphs: ["Few nations illustrate the practical complexity of governing ethnic and religious diversity as visibly as Malaysia, where a Malay Muslim majority coexists, not always without friction, alongside substantial Chinese and Indian minorities whose ancestors arrived primarily during the colonial period as laborers, traders, and administrators. That this arrangement has produced neither the ethnic conflict some observers once predicted nor the seamless integration others hoped for is, depending on which scholar one consults, either a qualified success or an unresolved tension merely managed rather than resolved.", "Malaysia's economic trajectory since independence has been shaped as much by deliberate policy intervention as by market forces, and it is this deliberate intervention - not simply favorable geography or foreign investment alone - that arguably explains the country's shift from a commodity-exporting economy into a diversified manufacturing and services hub within a single generation. Affirmative-action policies favoring the Malay majority, introduced to address disparities inherited from the colonial era, have simultaneously been credited with reducing poverty and criticized for distorting incentives in ways that may have slowed the very mobility they were designed to accelerate.", "Whether these preferential policies remain necessary decades after their introduction is a question that admits no confident answer, since available data can be read to support genuinely opposing conclusions. Some economists argue the policies should be phased out because Malay household wealth has, on average, converged substantially with that of other groups; others counter that averages obscure persistent disparities concentrated in specific regions and sectors, meaning phasing out support now could plausibly reverse gains that remain, in their view, more fragile than aggregate figures suggest.", "This same policy architecture has contributed, at least in part, to a pattern of skilled emigration that successive governments have struggled to reverse. Ethnic Chinese and Indian graduates, who may perceive fewer opportunities for advancement within a system that formally favors the majority, appear to emigrate at rates disproportionate to their share of the population, though researchers caution that emigration decisions are rarely reducible to any single identifiable cause alone and that global salary differentials likely play an independent, and possibly larger, role.", "Beyond ethnic policy, Malaysia's federal structure introduces its own layer of friction, particularly concerning the states of Sabah and Sarawak on Borneo, which joined the federation under an original agreement promising a degree of autonomy and revenue-sharing that many residents there argue has never been fully honored. Periodic renegotiation of these terms has become a recurring feature of national politics, one that intersects uncomfortably with the broader ethnic and religious questions already dividing peninsular Malaysia.", "Religious administration adds a further layer of complexity, since Malaysia operates a dual legal system in which civil law governs most matters while a separate framework of Islamic law applies specifically to Muslim citizens in areas such as family law. Non-Muslim minorities generally operate outside this second system entirely, yet disputes occasionally arise at the boundary where the two legal systems meet - most visibly in cases involving religious conversion or interfaith marriage - that expose how incompletely the two frameworks have been reconciled despite decades of coexistence.", "Looking forward, Malaysia has positioned itself as an aspiring hub for semiconductor assembly and renewable energy investment, sectors in which it already possesses meaningful existing infrastructure and decades of accumulated manufacturing expertise. Whether this ambition will be sufficient to escape what some economists term the middle-income trap - a plateau at which growth slows before an economy reaches high-income status - remains genuinely contested, since comparable economies in the region have pursued similar strategies with markedly different degrees of success.", "Taken as a whole, Malaysia's experience resists any simple verdict: its management of diversity has avoided the worst outcomes some once feared without fully resolving the underlying tensions, and its economic ascent has been real without yet guaranteeing the higher-income status the country has pursued for decades. Whether the coming years bring resolution or merely a continuation of this managed, unresolved balance is not a question the available evidence currently allows anyone to answer with confidence."], questions: [{ q: "According to the passage, what does the passage suggest most explains Malaysia's economic transformation?", options: ["Malaysia relied entirely on foreign investment for economic transformation.", "Favorable geography alone explains Malaysia's shift into manufacturing and services.", "Deliberate policy intervention, more than geography or foreign investment alone.", "Market forces operated completely independently of any government policy intervention."], answer: 2 }, { q: "The word \"converged\" in paragraph 3 is closest in meaning to _______.", options: ["become closer", "become identical", "become regulated", "diverged"], answer: 0 }, { q: "Which of the following best expresses the main idea of the passage?", options: ["Affirmative-action policies have completely eliminated all Malay-Chinese economic disparities.", "Malaysia's ethnic and religious tensions have already been fully and permanently resolved.", "Every multiethnic nation inevitably follows Malaysia's exact same developmental path.", "Malaysia's diversity and growth are real achievements alongside genuinely unresolved tensions."], answer: 3 }, { q: "According to the passage, which of the following is NOT mentioned as a source of tension within Malaysia?", options: ["Skilled emigration among ethnic Chinese and Indian graduates.", "A total ban on non-Muslim worship.", "Disputes over Sabah and Sarawak's promised revenue-sharing terms.", "A dual legal system separating civil law from Islamic law."], answer: 1 }, { q: "According to the passage, what do researchers caution about explanations for skilled emigration from Malaysia?", options: ["Ethnic Chinese graduates never actually emigrate at disproportionate rates.", "Global salary differences may play an independent, possibly larger role.", "Emigration decisions are rarely reducible to any single identifiable cause alone.", "Government policy is the sole and only cause of emigration."], answer: 2 }, { q: "The phrase \"this ambition\" in paragraph 7 refers to _______.", options: ["existing infrastructure itself", "Malaysia's tech-hub aspiration", "accumulated manufacturing expertise", "the middle-income trap"], answer: 1 }, { q: "The word \"aspiring\" in paragraph 7 is closest in meaning to _______.", options: ["already established as", "financially investing in", "perspiring", "striving to become"], answer: 3 }, { q: "According to the passage, how does the passage describe the relationship between Malaysia's civil and Islamic legal systems?", options: ["Disputes occasionally arise at the boundary where the two legal systems meet.", "Non-Muslims are fully governed by Islamic law in every matter.", "The two legal systems have been completely and formally merged.", "Civil law applies exclusively to Muslim citizens' family matters."], answer: 0 }, { q: "What can be inferred about Malaysia's path to high-income status, based on the passage?", options: ["Malaysia will certainly escape the middle-income trap within a few years.", "Higher household wealth convergence will directly cause faster semiconductor investment.", "Reaching it is plausible but not guaranteed.", "Sabah and Sarawak residents argue revenue-sharing terms remain unhonored."], answer: 2 }, { q: "What is the author's overall attitude toward Malaysia's experience with diversity and growth, as conveyed in the passage?", options: ["Uncritically celebratory of Malaysia's ethnic and economic policy successes.", "Analytically balanced, presenting real achievements alongside genuine unresolved difficulties.", "Deeply pessimistic that Malaysia's ethnic tensions will never be resolved.", "Mostly indifferent to whether Malaysia reaches high-income status eventually."], answer: 1 }] },
  ] },
];
